<h2>Estimate sales territory capacity</h2><p class="lead">Estimate how many qualified opportunities a territory/team can actively work from rep count, available selling time and average opportunity workload.</p><div class="notice">Use time-study data where possible. The goal is to expose workload assumptions instead of assigning a universal number of accounts or opportunities per rep.</div><div class="form-grid"><div class="field"><label for="reps">Active reps in territory</label><input id="reps" type="number" value="5" min="0" step="1"></div><div class="field"><label for="days">Selling days per month</label><input id="days" type="number" value="20" min="0" step="any"></div><div class="field"><label for="hours">Productive selling hours per day</label><input id="hours" type="number" value="5" min="0" step="any"></div><div class="field"><label for="util">Share of productive time available for opportunities (%)</label><input id="util" type="number" value="70" min="0" max="100" step="any"></div><div class="field"><label for="peropp">Average rep hours per active opportunity / month</label><input id="peropp" type="number" value="4" min="0.001" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Available opportunity hours</span><strong id="hourscap">—</strong></div><div class="metric"><span>Active opportunity capacity</span><strong id="capacity">—</strong></div><div class="metric"><span>Capacity per rep</span><strong id="perrep">—</strong></div><div class="metric"><span>Hours per additional opportunity</span><strong id="spare">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('hourscap').textContent='—';$('capacity').textContent='—';$('perrep').textContent='—';$('spare').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const r=num('reps'),d=num('days'),h=num('hours'),u=num('util')/100,p=num('peropp');if(!(r>=0&&d>=0&&h>=0&&u>=0&&u<=1&&p>0))throw 0;const hrs=r*d*h*u,cap=hrs/p;$('hourscap').textContent=fmt(hrs,1)+' h/month';$('capacity').textContent=fmt(cap,1)+' opps';$('perrep').textContent=r>0?fmt(cap/r,1)+' opps':'—';$('spare').textContent=fmt(p,1)+' rep-hours';$('note').textContent='This is a workload capacity model, not a market-potential model. Opportunity complexity, travel, account coverage and admin time can make actual capacity lower.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
